import { readFile } from 'node:fs/promises'
import path from 'node:path'

import type { Page } from '@playwright/test'

export async function loadBuiltApp(page: Page, entry: 'controlled' | 'hydration' | 'index' = 'index') {
  await page.route('http://dialog.test/**', async (route) => {
    const pathname = new URL(route.request().url()).pathname.replace(/^\//, '') || 'index.html'
    const filePath = path.resolve('dist', pathname)
    const contentType = pathname.endsWith('.html')
      ? 'text/html'
      : pathname.endsWith('.css')
        ? 'text/css'
        : 'text/javascript'
    await route.fulfill({ body: await readFile(filePath), contentType })
  })
  await page.goto(`http://dialog.test/${entry === 'index' ? '' : `${entry}.html`}`)
  const initialButton =
    entry === 'controlled'
      ? 'Open controlled dialog'
      : entry === 'hydration'
        ? 'Open hydrated dialog'
        : 'Edit profile'
  await page.getByRole('button', { name: initialButton }).waitFor()
}

import {
  createContext,
  forwardRef,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type MutableRefObject,
  type ReactNode,
  type Ref,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'

import { registerFocusScope } from './dialog/focus-management'

export type DialogOpenChangeReason =
  | 'close-button'
  | 'escape-key'
  | 'outside-pointer'
  | 'trigger'

export type DialogOpenChangeDetails = {
  nativeEvent?: Event
  reason: DialogOpenChangeReason
}

export type DialogProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void
  open?: boolean
}

type DialogContextValue = {
  contentId: string
  defaultDescriptionId: string
  defaultTitleId: string
  dialogId: symbol
  descriptionId: string | null
  open: boolean
  registerDescription: (id: string) => () => void
  registerTitle: (id: string) => () => void
  requestOpenChange: (open: boolean, details: DialogOpenChangeDetails) => void
  titleId: string | null
  triggerRef: MutableRefObject<HTMLButtonElement | null>
}

const DialogContext = createContext<DialogContextValue | null>(null)
const PortalContext = createContext<RefObject<HTMLDivElement | null> | null>(null)
const useIsomorphicLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect

function useDialogContext(component: string) {
  const context = useContext(DialogContext)
  if (!context) throw new Error(`${component} must be rendered inside <Dialog>.`)
  return context
}

function useLatest<T>(value: T) {
  const ref = useRef(value)
  ref.current = value
  return ref
}

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === 'function') ref(value)
  else if (ref) ref.current = value
}

export function Dialog({ children, defaultOpen = false, onOpenChange, open: controlledOpen }: DialogProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = controlledOpen !== undefined
  const open = isControlled ? controlledOpen : uncontrolledOpen
  const openRef = useLatest(open)
  const controlledRef = useLatest(isControlled)
  const onOpenChangeRef = useLatest(onOpenChange)
  const triggerRef = useRef<HTMLButtonElement | null>(null)
  const reactId = useId()
  const contentId = `dialog-${reactId}-content`
  const defaultTitleId = `dialog-${reactId}-title`
  const defaultDescriptionId = `dialog-${reactId}-description`
  const dialogId = useMemo(() => Symbol('dialog'), [])
  const [titleId, setTitleId] = useState<string | null>(null)
  const [descriptionId, setDescriptionId] = useState<string | null>(null)

  const requestOpenChange = useCallback((nextOpen: boolean, details: DialogOpenChangeDetails) => {
    if (openRef.current === nextOpen) return
    if (!controlledRef.current) setUncontrolledOpen(nextOpen)
    onOpenChangeRef.current?.(nextOpen, details)
  }, [controlledRef, onOpenChangeRef, openRef])

  const registerTitle = useCallback((id: string) => {
    setTitleId(id)
    return () => setTitleId((current) => (current === id ? null : current))
  }, [])
  const registerDescription = useCallback((id: string) => {
    setDescriptionId(id)
    return () => setDescriptionId((current) => (current === id ? null : current))
  }, [])

  const value = useMemo<DialogContextValue>(() => ({
    contentId,
    defaultDescriptionId,
    defaultTitleId,
    descriptionId,
    dialogId,
    open,
    registerDescription,
    registerTitle,
    requestOpenChange,
    titleId,
    triggerRef,
  }), [contentId, defaultDescriptionId, defaultTitleId, descriptionId, dialogId, open,
    registerDescription, registerTitle, requestOpenChange, titleId])

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

export const DialogTrigger = forwardRef<HTMLButtonElement, ButtonHTMLAttributes<HTMLButtonElement>>(
  function DialogTrigger({ onClick, type = 'button', ...props }, forwardedRef) {
    const context = useDialogContext('DialogTrigger')
    return (
